{"command":"cat << 'EOF' > test_gz.go
package main

import (
	"bufio"
	"compress/gzip"
	"fmt"
	"io"
	"os"
)

type ReadCloserBuf struct {
	io.ReadCloser
	br *bufio.Reader
}

func OpenStream(path string) (io.Closer, *bufio.Reader, error) {
	var r io.ReadCloser
	if path == "stdin" || path == "-" || path == "" {
		r = io.NopCloser(os.Stdin)
	} else {
		f, err := os.Open(path)
		if err != nil {
			return nil, nil, err
		}
		r = f
	}
	br := bufio.NewReader(r)
	peek, err := br.Peek(2)
	if err == nil && len(peek) == 2 && peek[0] == 0x1f && peek[1] == 0x8b {
		gzr, err := gzip.NewReader(br)
		if err == nil {
			return gzr, bufio.NewReader(gzr), nil
		}
	}
	return r, br, nil
}

func main() {
	_, br1, err := OpenStream("data/knownGene.hg18.chr21.short.bed")
	if err != nil { panic(err) }
	line1, _ := br1.ReadString('\n')
	fmt.Print("Plain:", line1)

	_, br2, err := OpenStream("data/aluY.chr1.bed.gz")
	if err != nil { panic(err) }
	line2, _ := br2.ReadString('\n')
	fmt.Print("Gzip :", line2)
}
EOF
go run test_gz.go
rm test_gz.go
"}

