{"command":"cat << 'EOF' > src/bed.go
package main

import (
	"bufio"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

type BedRecord struct {
	Chrom  string
	Start  int64
	End    int64
	Name   string
	Score  string
	Strand string
	Fields []string
	Raw    string
}

func (r *BedRecord) Length() int64 {
	return r.End - r.Start
}

func OpenStream(path string) (io.Closer, *bufio.Reader, error) {
	var r io.ReadCloser
	if path == "stdin" || path == "-" || path == "" {
		r = io.NopCloser(os.Stdin)
	} else {
		f, err := os.Open(path)
		if err != nil {
			return nil, nil, err
		}
		r = f
	}
	br := bufio.NewReader(r)
	peek, err := br.Peek(2)
	if err == nil && len(peek) == 2 && peek[0] == 0x1f && peek[1] == 0x8b {
		gzr, err := gzip.NewReader(br)
		if err == nil {
			return gzr, bufio.NewReader(gzr), nil
		}
	}
	return r, br, nil
}

func ReadBedRecords(path string, printHeader bool) ([]BedRecord, []string, error) {
	closer, br, err := OpenStream(path)
	if err != nil {
		return nil, nil, err
	}
	defer closer.Close()

	var records []BedRecord
	var headers []string
	firstData := false

	for {
		line, err := br.ReadString('\n')
		if len(line) == 0 && err != nil {
			break
		}
		trimmed := strings.TrimRight(line, "\r\n")
		if len(trimmed) == 0 {
			if err != nil {
				break
			}
			continue
		}

		if !firstData && (strings.HasPrefix(trimmed, "#") || strings.HasPrefix(trimmed, "browser") || strings.HasPrefix(trimmed, "track") || strings.HasPrefix(trimmed, "gff") || strings.HasPrefix(trimmed, "##fileformat")) {
			headers = append(headers, trimmed)
			if printHeader {
				fmt.Println(trimmed)
			}
			if err != nil {
				break
			}
			continue
		}
		firstData = true

		fields := strings.Split(trimmed, "\t")
		if len(fields) < 3 {
			fields = strings.Fields(trimmed)
			if len(fields) < 3 {
				if err != nil {
					break
				}
				continue
			}
		}

		start, err1 := strconv.ParseInt(fields[1], 10, 64)
		end, err2 := strconv.ParseInt(fields[2], 10, 64)
		if err1 != nil || err2 != nil {
			if err != nil {
				break
			}
			continue
		}

		rec := BedRecord{
			Chrom:  fields[0],
			Start:  start,
			End:    end,
			Fields: fields,
			Raw:    trimmed,
		}
		if len(fields) > 3 {
			rec.Name = fields[3]
		}
		if len(fields) > 4 {
			rec.Score = fields[4]
		}
		if len(fields) > 5 {
			rec.Strand = fields[5]
		} else {
			rec.Strand = "."
		}

		records = append(records, rec)

		if err != nil {
			break
		}
	}

	return records, headers, nil
}

type Genome map[string]int64

func ReadGenome(path string) (Genome, []string, error) {
	closer, br, err := OpenStream(path)
	if err != nil {
		return nil, nil, err
	}
	defer closer.Close()

	g := make(Genome)
	var order []string

	for {
		line, err := br.ReadString('\n')
		if len(line) == 0 && err != nil {
			break
		}
		trimmed := strings.TrimRight(line, "\r\n")
		if len(trimmed) == 0 || strings.HasPrefix(trimmed, "#") {
			if err != nil {
				break
			}
			continue
		}
		fields := strings.Fields(trimmed)
		if len(fields) >= 2 {
			sz, errParse := strconv.ParseInt(fields[1], 10, 64)
			if errParse == nil {
				g[fields[0]] = sz
				order = append(order, fields[0])
			}
		}
		if err != nil {
			break
		}
	}
	return g, order, nil
}

func OverlapBP(s1, e1, s2, e2 int64) int64 {
	maxS := s1
	if s2 > maxS {
		maxS = s2
	}
	minE := e1
	if e2 < minE {
		minE = e2
	}
	if minE > maxS {
		return minE - maxS
	}
	return 0
}

func Overlaps(a, b *BedRecord, minFracA, minFracB float64, reciprocal, either, sameStrand, diffStrand bool) bool {
	if a.Chrom != b.Chrom {
		return false
	}
	if sameStrand {
		if a.Strand != "." && b.Strand != "." && a.Strand != b.Strand {
			return false
		}
	}
	if diffStrand {
		if a.Strand != "." && b.Strand != "." && a.Strand == b.Strand {
			return false
		}
	}
	bp := OverlapBP(a.Start, a.End, b.Start, b.End)
	if bp <= 0 {
		return false
	}

	lenA := float64(a.Length())
	lenB := float64(b.Length())

	fracA := float64(bp) / lenA
	fracB := float64(bp) / lenB

	if reciprocal {
		return fracA >= minFracA && fracB >= minFracA
	}
	if either {
		return fracA >= minFracA || fracB >= minFracB
	}
	return fracA >= minFracA && fracB >= minFracB
}
EOF
"}

