func runMerge(args []string) {
	inputFile := "stdin"
	sameStrand := false
	var specifyStrand string
	maxDist := int64(0)
	var colSpec string
	var opSpec string
	printHeader := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i":
			if i+1 < len(args) {
				inputFile = args[i+1]
				i++
			}
		case "-s":
			sameStrand = true
		case "-S":
			if i+1 < len(args) {
				specifyStrand = args[i+1]
				i++
			}
		case "-d":
			if i+1 < len(args) {
				maxDist, _ = strconv.ParseInt(args[i+1], 10, 64)
				i++
			}
		case "-c":
			if i+1 < len(args) {
				colSpec = args[i+1]
				i++
			}
		case "-o":
			if i+1 < len(args) {
				opSpec = args[i+1]
				i++
			}
		case "-header":
			printHeader = true
		}
	}

	records, _, err := ReadBedRecords(inputFile, printHeader)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	if len(records) == 0 {
		return
	}

	// Parse column and op specs
	var cols []int
	if colSpec != "" {
		for _, cs := range strings.Split(colSpec, ",") {
			c, _ := strconv.Atoi(cs)
			cols = append(cols, c-1) // convert 1-based to 0-based
		}
	}
	var ops []string
	if opSpec != "" {
		ops = strings.Split(opSpec, ",")
	}

	// Group records by chromosome and strand (if -s)
	type key struct {
		chrom  string
		strand string
	}
	groups := make(map[key][]BedRecord)
	var order []key
