func applyOp(vals []string, op string) string {
	if len(vals) == 0 {
		return "."
	}
	switch op {
	case "sum":
		sum := 0.0
		for _, v := range vals {
			f, _ := strconv.ParseFloat(v, 64)
			sum += f
		}
		return fmt.Sprintf("%.6g", sum)
	case "min":
		minV := 1e308
		for _, v := range vals {
			f, _ := strconv.ParseFloat(v, 64)
			if f < minV {
