			}
		}
		return fmt.Sprintf("%.6g", minV)
	case "max":
		maxV := -1e308
		for _, v := range vals {
			f, _ := strconv.ParseFloat(v, 64)
			if f > maxV {
				maxV = f
			}
		}
		return fmt.Sprintf("%.6g", maxV)
	case "mean":
		sum := 0.0
		for _, v := range vals {
			f, _ := strconv.ParseFloat(v, 64)
			sum += f
		}
		return fmt.Sprintf("%.6g", sum/float64(len(vals)))
	case "count":
		return strconv.Itoa(len(vals))
	case "count_distinct":
		seen := make(map[string]bool)
		for _, v := range vals {
			seen[v] = true
		}
		return strconv.Itoa(len(seen))
	case "collapse":
		return strings.Join(vals, ",")
	case "distinct":
		var u []string
		seen := make(map[string]bool)
		for _, v := range vals {
			if !seen[v] {
				seen[v] = true
				u = append(u, v)
			}
		}
		return strings.Join(u, ",")
	case "first":
		return vals[0]
	case "last":
		return vals[len(vals)-1]
	default:
		return strings.Join(vals, ",")
	}
}
