package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func runSlop(args []string) {
	inputFile := "stdin"
	var genomeFile string
	var bVal, lVal, rVal float64
	hasB, hasL, hasR := false, false, false
	stranded := false
	pct := false
	printHeader := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i":
			if i+1 < len(args) {
				inputFile = args[i+1]
				i++
			}
		case "-g":
			if i+1 < len(args) {
				genomeFile = args[i+1]
				i++
			}
		case "-b":
			if i+1 < len(args) {
				bVal, _ = strconv.ParseFloat(args[i+1], 64)
				hasB = true
				i++
			}
		case "-l":
			if i+1 < len(args) {
				lVal, _ = strconv.ParseFloat(args[i+1], 64)
				hasL = true
				i++
			}
		case "-r":
			if i+1 < len(args) {
				rVal, _ = strconv.ParseFloat(args[i+1], 64)
				hasR = true
				i++
			}
		case "-s":
			stranded = true
		case "-pct":
			pct = true
		case "-header":
			printHeader = true
		}
	}

	if genomeFile == "" {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/slop.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	genome, _, errG := ReadGenome(genomeFile)
	if errG != nil {
		fmt.Fprintf(os.Stderr, "Error reading genome: %v\n", errG)
		os.Exit(1)
	}

	records, _, err := ReadBedRecords(inputFile, printHeader)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	for _, r := range records {
		chromSize, ok := genome[r.Chrom]
		if !ok {
			chromSize = 1e18 // unbounded if unknown chrom
		}

		leftAdd := int64(0)
		rightAdd := int64(0)

		if hasB {
			if pct {
				leftAdd = int64(bVal * float64(r.Length()))
				rightAdd = leftAdd
			} else {
				leftAdd = int64(bVal)
				rightAdd = int64(bVal)
			}
		} else {
			if hasL {
				if pct {
					leftAdd = int64(lVal * float64(r.Length()))
				} else {
					leftAdd = int64(lVal)
				}
			}
			if hasR {
				if pct {
					rightAdd = int64(rVal * float64(r.Length()))
				} else {
					rightAdd = int64(rVal)
				}
			}
		}

		if stranded && r.Strand == "-" {
			leftAdd, rightAdd = rightAdd, leftAdd
		}

		newStart := r.Start - leftAdd
		if newStart < 0 {
			newStart = 0
		}
		newEnd := r.End + rightAdd
		if newEnd > chromSize {
			newEnd = chromSize
		}

		outFields := make([]string, len(r.Fields))
		copy(outFields, r.Fields)
		outFields[1] = strconv.FormatInt(newStart, 10)
		outFields[2] = strconv.FormatInt(newEnd, 10)
		fmt.Println(strings.Join(outFields, "\t"))
	}
