{"command":"cat << 'EOF' > src/complement.go
package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
)

func runComplement(args []string) {
	inputFile := "stdin"
	var genomeFile string
	limitChroms := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i":
			if i+1 < len(args) {
				inputFile = args[i+1]
				i++
			}
		case "-g":
			if i+1 < len(args) {
				genomeFile = args[i+1]
				i++
			}
		case "-L":
			limitChroms = true
		}
	}

	if genomeFile == "" {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/complement.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	genome, orderList, errG := ReadGenome(genomeFile)
	if errG != nil {
		fmt.Fprintf(os.Stderr, "Error reading genome: %v\n", errG)
		os.Exit(1)
	}

	records, _, err := ReadBedRecords(inputFile, false)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	// Group records by chrom
	chromRecs := make(map[string][]BedRecord)
	seenInInput := make(map[string]bool)
	for _, r := range records {
		chromRecs[r.Chrom] = append(chromRecs[r.Chrom], r)
		seenInInput[r.Chrom] = true
	}

	for _, chrom := range orderList {
		chromSize, ok := genome[chrom]
		if !ok {
			continue
		}
		if limitChroms && !seenInInput[chrom] {
			continue
		}

		recs := chromRecs[chrom]
		sort.SliceStable(recs, func(i, j int) bool {
			if recs[i].Start != recs[j].Start {
				return recs[i].Start < recs[j].Start
			}
			return recs[i].End < recs[j].End
		})

		// Merge overlapping intervals
		var mergedStarts []int64
		var mergedEnds []int64
		for _, r := range recs {
			if len(mergedStarts) == 0 {
				mergedStarts = append(mergedStarts, r.Start)
				mergedEnds = append(mergedEnds, r.End)
			} else {
				lastIdx := len(mergedStarts) - 1
				if r.Start <= mergedEnds[lastIdx] {
					if r.End > mergedEnds[lastIdx] {
						mergedEnds[lastIdx] = r.End
					}
				} else {
					mergedStarts = append(mergedStarts, r.Start)
					mergedEnds = append(mergedEnds, r.End)
				}
			}
		}

		// Print complement gaps
		currPos := int64(0)
		for idx := 0; idx < len(mergedStarts); idx++ {
			s, e := mergedStarts[idx], mergedEnds[idx]
			if currPos < s {
				fmt.Printf("%s\t%d\t%d\n", chrom, currPos, s)
			}
			if e > currPos {
				currPos = e
			}
		}
		if currPos < chromSize {
			fmt.Printf("%s\t%d\t%d\n", chrom, currPos, chromSize)
		}
	}
}
