		}

		if uniqueA {
			if len(hits) > 0 {
				fmt.Println(ra.Raw)
			}
			continue
		}

		for _, hb := range hits {
			fmt.Printf("%s\t%s\n", ra.Raw, hb.Raw)
		}
	}
}
