{"command":"cat << 'EOF' > src/closest.go
package main

import (
	"fmt"
	"math"
	"os"
	"strconv"
)

func runClosest(args []string) {
	var fileA string
	var filesB []string
	reportDist := false
	sameStrand := false
	diffStrand := false
	ignoreOverlaps := false
	ignoreUpstream := false
	ignoreDownstream := false
	forceUpstream := false
	forceDownstream := false
	printHeader := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-a":
			if i+1 < len(args) {
				fileA = args[i+1]
				i++
			}
		case "-b":
			for i+1 < len(args) && args[i+1][0] != '-' {
				filesB = append(filesB, args[i+1])
				i++
			}
		case "-d":
			reportDist = true
		case "-s":
			sameStrand = true
		case "-S":
			diffStrand = true
		case "-io":
			ignoreOverlaps = true
		case "-iu":
			ignoreUpstream = true
		case "-id":
			ignoreDownstream = true
		case "-fu":
			forceUpstream = true
		case "-fd":
			forceDownstream = true
		case "-header":
			printHeader = true
		}
	}

	if fileA == "" || len(filesB) == 0 {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/closest.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	recordsA, _, err := ReadBedRecords(fileA, printHeader)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading A: %v\n", err)
		os.Exit(1)
	}

	var allRecordsB []BedRecord
	for _, fb := range filesB {
		recsB, _, err := ReadBedRecords(fb, false)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading B: %v\n", err)
			os.Exit(1)
		}
		allRecordsB = append(allRecordsB, recsB...)
	}

	bByChrom := make(map[string][]BedRecord)
	for _, rb := range allRecordsB {
		bByChrom[rb.Chrom] = append(bByChrom[rb.Chrom], rb)
	}

	for _, ra := range recordsA {
		bList := bByChrom[ra.Chrom]

		minDist := int64(math.MaxInt64)
		var bestHits []BedRecord
		var bestDists []int64

		for _, rb := range bList {
			if sameStrand && (ra.Strand == "." || rb.Strand == "." || ra.Strand != rb.Strand) {
				continue
			}
			if diffStrand && (ra.Strand == "." || rb.Strand == "." || ra.Strand == rb.Strand) {
				continue
			}

			// Distance calculation:
			// If overlapping: dist = 0
			// If B is right of A (rb.Start >= ra.End): dist = rb.Start - ra.End
			// If B is left of A (rb.End <= ra.Start): dist = ra.Start - rb.End
			var dist int64
			isUpstream := false   // B is upstream of A
			isDownstream := false // B is downstream of A

			if rb.End <= ra.Start {
				dist = ra.Start - rb.End
				if ra.Strand == "-" {
					isDownstream = true
				} else {
					isUpstream = true
				}
			} else if rb.Start >= ra.End {
				dist = rb.Start - ra.End
				if ra.Strand == "-" {
					isUpstream = true
				} else {
					isDownstream = true
				}
			} else {
				dist = 0
			}

			if ignoreOverlaps && dist == 0 {
				continue
			}
			if ignoreUpstream && isUpstream {
				continue
			}
			if ignoreDownstream && isDownstream {
				continue
			}
			if forceUpstream && !isUpstream {
				continue
			}
			if forceDownstream && !isDownstream {
				continue
			}

			if dist < minDist {
				minDist = dist
				bestHits = []BedRecord{rb}
				bestDists = []int64{dist}
			} else if dist == minDist {
				bestHits = append(bestHits, rb)
				bestDists = append(bestDists, dist)
			}
		}

		if len(bestHits) == 0 {
			numBCols := 3
			if len(allRecordsB) > 0 {
				numBCols = len(allRecordsB[0].Fields)
			}
			nullB := make([]string, numBCols)
			nullB[0] = "."
			nullB[1] = "-1"
			nullB[2] = "-1"
			for k := 3; k < numBCols; k++ {
				nullB[k] = "."
			}
			if reportDist {
				fmt.Printf("%s\t%s\t-1\n", ra.Raw, formatCols(nullB))
			} else {
				fmt.Printf("%s\t%s\n", ra.Raw, formatCols(nullB))
			}
		} else {
			for i, hb := range bestHits {
				d := bestDists[i]
				if reportDist {
					fmt.Printf("%s\t%s\t%d\n", ra.Raw, hb.Raw, d)
				} else {
					fmt.Printf("%s\t%s\n", ra.Raw, hb.Raw)
				}
			}
		}
	}
}

func formatCols(fields []string) string {
	var res string
	for i, f := range fields {
		if i > 0 {
			res += "\t"
		}
		res += f
	}
	return res
}
EOF
