					minDist = 0
					bestHits = []BedRecord{rb}
					bestDists = []int64{0}
				} else {
					bestHits = append(bestHits, rb)
					bestDists = append(bestDists, 0)
				}
			} else if !hasOverlap {
				if dist < minDist {
					minDist = dist
					bestHits = []BedRecord{rb}
					bestDists = []int64{dist}
				} else if dist == minDist {
					bestHits = append(bestHits, rb)
					bestDists = append(bestDists, dist)
				}
			}
		}

		if len(bestHits) == 0 {
			numBCols := 3
			if len(allRecordsB) > 0 {
				numBCols = len(allRecordsB[0].Fields)
			}
			nullB := make([]string, numBCols)
			nullB[0] = "."
			nullB[1] = "-1"
			nullB[2] = "-1"
			for k := 3; k < numBCols; k++ {
				nullB[k] = "."
			}
			if reportDist {
				fmt.Printf("%s\t%s\t-1\n", ra.Raw, formatCols(nullB))
			} else {
				fmt.Printf("%s\t%s\n", ra.Raw, formatCols(nullB))
			}
		} else {
			for i, hb := range bestHits {
				d := bestDists[i]
				if reportDist {
					fmt.Printf("%s\t%s\t%d\n", ra.Raw, hb.Raw, d)
				} else {
					fmt.Printf("%s\t%s\n", ra.Raw, hb.Raw)
				}
			}
		}
	}
}

func formatCols(fields []string) string {
	var res string
	for i, f := range fields {
		if i > 0 {
			res += "\t"
		}
		res += f
	}
	return res
}
