		recsB, _, err := ReadBedRecords(fb, false)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading B: %v\n", err)
			os.Exit(1)
		}
		allRecordsB = append(allRecordsB, recsB...)
	}

