	allDepthsHist := make(map[int64]int64)
	totalABp := int64(0)

	for _, ra := range recordsA {
		bList := bByChrom[ra.Chrom]
		lenA := ra.Length()
		if lenA <= 0 {
			continue
		}
		totalABp += lenA

		depthArray := make([]int32, lenA)
		numHits := 0

		for _, rb := range bList {
			if Overlaps(&ra, &rb, minFracA, minFracB, reciprocal, either, sameStrand, diffStrand) {
				numHits++
				// Mark depth in depthArray
				s := rb.Start - ra.Start
				if s < 0 {
					s = 0
				}
				e := rb.End - ra.Start
				if e > lenA {
					e = lenA
				}
				for pos := s; pos < e; pos++ {
					depthArray[pos]++
				}
			}
		}

		if depthMode {
			for pos := int64(0); pos < lenA; pos++ {
				fmt.Printf("%s\t%d\t%d\n", ra.Raw, pos+1, depthArray[pos])
			}
			continue
		}

		// Count depth histogram for this feature
		depthCounts := make(map[int64]int64)
		coveredBp := int64(0)
		totalDepthSum := int64(0)

		for pos := int64(0); pos < lenA; pos++ {
			d := int64(depthArray[pos])
			depthCounts[d]++
			allDepthsHist[d]++
			totalDepthSum += d
			if d > 0 {
				coveredBp++
			}
		}

		if meanMode {
			meanDepth := float64(totalDepthSum) / float64(lenA)
			fmt.Printf("%s\t%.7f\n", ra.Raw, meanDepth)
			continue
		}

		if histMode {
			// Print histogram per feature
			// Collect sorted depth keys
			var depths []int64
			for d := range depthCounts {
				depths = append(depths, d)
			}
			sortInt64s(depths)

			for _, d := range depths {
				cnt := depthCounts[d]
				frac := float64(cnt) / float64(lenA)
				fmt.Printf("%s\t%d\t%d\t%d\t%.7f\n", ra.Raw, d, cnt, lenA, frac)
			}
			continue
		}

		// Default coverage mode
		fracCovered := float64(coveredBp) / float64(lenA)
		fmt.Printf("%s\t%d\t%d\t%d\t%.7f\n", ra.Raw, numHits, coveredBp, lenA, fracCovered)
	}

	if histMode && totalABp > 0 {
		// Output overall all-features histogram
		var depths []int64
		for d := range allDepthsHist {
			depths = append(depths, d)
		}
		sortInt64s(depths)

		for _, d := range depths {
			cnt := allDepthsHist[d]
			frac := float64(cnt) / float64(totalABp)
			fmt.Printf("all\t%d\t%d\t%d\t%.7f\n", d, cnt, totalABp, frac)
		}
	}
}

func sortInt64s(a []int64) {
	for i := 0; i < len(a); i++ {
		for j := i + 1; j < len(a); j++ {
			if a[j] < a[i] {
				a[i], a[j] = a[j], a[i]
			}
		}
	}
}
