package main

import (
	"fmt"
	"os"
	"strconv"
)

func runGenomeCov(args []string) {
	inputFile := "stdin"
	var genomeFile string
	bgMode := false
	bgaMode := false
	depth1Mode := false
	depth0Mode := false
	maxDepth := int64(-1)
	scale := 1.0

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i", "-ibam":
			if i+1 < len(args) {
				inputFile = args[i+1]
				i++
			}
		case "-g":
			if i+1 < len(args) {
				genomeFile = args[i+1]
				i++
			}
		case "-bg":
			bgMode = true
		case "-bga":
			bgaMode = true
		case "-d":
			depth1Mode = true
		case "-dz":
			depth0Mode = true
		case "-max":
			if i+1 < len(args) {
				maxDepth, _ = strconv.ParseInt(args[i+1], 10, 64)
				i++
			}
		case "-scale":
			if i+1 < len(args) {
				scale, _ = strconv.ParseFloat(args[i+1], 64)
				i++
			}
		}
	}

	if genomeFile == "" {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/genomecov.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	genome, orderList, errG := ReadGenome(genomeFile)
	if errG != nil {
		fmt.Fprintf(os.Stderr, "Error reading genome: %v\n", errG)
		os.Exit(1)
	}

	records, _, err := ReadBedRecords(inputFile, false)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	chromRecs := make(map[string][]BedRecord)
	for _, r := range records {
		chromRecs[r.Chrom] = append(chromRecs[r.Chrom], r)
	}

	genomeDepths := make(map[int64]int64)
	totalGenomeBp := int64(0)

	for _, chrom := range orderList {
		chromSize, ok := genome[chrom]
		if !ok {
			continue
		}
		totalGenomeBp += chromSize

		depths := make([]int32, chromSize)
		recs := chromRecs[chrom]

		for _, r := range recs {
			s := r.Start
			if s < 0 {
				s = 0
			}
			e := r.End
			if e > chromSize {
				e = chromSize
			}
			for pos := s; pos < e; pos++ {
				depths[pos]++
			}
		}

		if depth1Mode || depth0Mode {
			offset := int64(0)
			if depth1Mode {
				offset = 1
			}
			for pos := int64(0); pos < chromSize; pos++ {
				d := float64(depths[pos]) * scale
				if scale != 1.0 {
					fmt.Printf("%s\t%d\t%.6g\n", chrom, pos+offset, d)
				} else {
					fmt.Printf("%s\t%d\t%d\n", chrom, pos+offset, depths[pos])
				}
			}
			continue
		}

		if bgMode || bgaMode {
			var curStart int64 = 0
			curDepth := depths[0]

			for pos := int64(1); pos < chromSize; pos++ {
				if depths[pos] != curDepth {
					if bgaMode || curDepth > 0 {
						printBgLine(chrom, curStart, pos, curDepth, scale)
					}
					curStart = pos
					curDepth = depths[pos]
				}
			}
			if bgaMode || curDepth > 0 {
				printBgLine(chrom, curStart, chromSize, curDepth, scale)
			}
			continue
		}

		// Histogram mode for this chrom
		chromDepths := make(map[int64]int64)
		for pos := int64(0); pos < chromSize; pos++ {
			d := int64(depths[pos])
			if maxDepth >= 0 && d > maxDepth {
				d = maxDepth
			}
			chromDepths[d]++
			genomeDepths[d]++
		}

		var depthKeys []int64
		for d := range chromDepths {
			depthKeys = append(depthKeys, d)
		}
		sortInt64s(depthKeys)

		for _, d := range depthKeys {
			cnt := chromDepths[d]
			frac := float32(cnt) / float32(chromSize)
			fmt.Printf("%s\t%d\t%d\t%d\t%.7g\n", chrom, d, cnt, chromSize, frac)
		}
	}

	if !bgMode && !bgaMode && !depth1Mode && !depth0Mode && totalGenomeBp > 0 {
		var depthKeys []int64
		for d := range genomeDepths {
			depthKeys = append(depthKeys, d)
		}
		sortInt64s(depthKeys)

		for _, d := range depthKeys {
			cnt := genomeDepths[d]
			frac := float32(cnt) / float32(totalGenomeBp)
			fmt.Printf("genome\t%d\t%d\t%d\t%.7g\n", d, cnt, totalGenomeBp, frac)
		}
	}
}

func printBgLine(chrom string, start, end int64, depth int32, scale float64) {
	if scale != 1.0 {
		d := float64(depth) * scale
		fmt.Printf("%s\t%d\t%d\t%.6g\n", chrom, start, end, d)
	} else {
		fmt.Printf("%s\t%d\t%d\t%d\n", chrom, start, end, depth)
	}
}
