				filesB = append(filesB, args[i+1])
				i++
			}
		case "-c":
			if i+1 < len(args) {
				colSpec = args[i+1]
				i++
			}
		case "-o":
			if i+1 < len(args) {
				opSpec = args[i+1]
				i++
			}
		case "-null":
			if i+1 < len(args) {
				nullVal = args[i+1]
				i++
			}
		case "-s":
			sameStrand = true
		case "-S":
			diffStrand = true
		case "-f":
			if i+1 < len(args) {
				minFracA, _ = strconv.ParseFloat(args[i+1], 64)
				i++
			}
		case "-F":
			if i+1 < len(args) {
				minFracB, _ = strconv.ParseFloat(args[i+1], 64)
				i++
			}
		case "-r":
			reciprocal = true
		case "-e":
			either = true
		case "-header":
			printHeader = true
		}
	}

	if fileA == "" || len(filesB) == 0 {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/map.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	recordsA, _, err := ReadBedRecords(fileA, printHeader)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading A: %v\n", err)
		os.Exit(1)
	}

	var allRecordsB []BedRecord
	for _, fb := range filesB {
		recsB, _, err := ReadBedRecords(fb, false)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading B: %v\n", err)
			os.Exit(1)
		}
		allRecordsB = append(allRecordsB, recsB...)
	}

	bByChrom := make(map[string][]BedRecord)
	for _, rb := range allRecordsB {
		bByChrom[rb.Chrom] = append(bByChrom[rb.Chrom], rb)
	}

	var cols []int
	if colSpec != "" {
		for _, cs := range strings.Split(colSpec, ",") {
			c, _ := strconv.Atoi(cs)
			cols = append(cols, c-1)
		}
	}
	var ops []string
	if opSpec != "" {
		ops = strings.Split(opSpec, ",")
	}

	for _, ra := range recordsA {
		bList := bByChrom[ra.Chrom]
		var hits []BedRecord

		for _, rb := range bList {
			if Overlaps(&ra, &rb, minFracA, minFracB, reciprocal, either, sameStrand, diffStrand) {
				hits = append(hits, rb)
			}
		}

		outLine := ra.Raw
		if len(hits) == 0 {
			for range cols {
				outLine += "\t" + nullVal
			}
		} else {
			for i, colIdx := range cols {
				op := "collapse"
				if i < len(ops) {
					op = ops[i]
				}
				var vals []string
				for _, hb := range hits {
					if colIdx < len(hb.Fields) {
						vals = append(vals, hb.Fields[colIdx])
					} else {
						vals = append(vals, ".")
					}
				}
				res := applyOp(vals, op)
				outLine += "\t" + res
			}
		}
		fmt.Println(outLine)
	}
}
