				}
				i++
			}
		}
	}

	closer, br, err := OpenStream(inputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}
	defer closer.Close()

	for {
		line, err := br.ReadString('\n')
		if len(line) == 0 && err != nil {
			break
		}
		trimmed := strings.TrimRight(line, "\r\n")
		if len(trimmed) == 0 {
			if err != nil {
				break
			}
			continue
		}

		fields := strings.Split(trimmed, "\t")
		if len(cols) == 0 {
			fmt.Println(trimmed)
