				break
			}
			continue
		}

		// Split targeted column values
		colVals := make([][]string, len(cols))
		maxLen := 1
		for idx, colIdx := range cols {
			if colIdx < len(fields) {
				parts := strings.Split(fields[colIdx], ",")
				colVals[idx] = parts
				if len(parts) > maxLen {
					maxLen = len(parts)
				}
			}
		}

		for k := 0; k < maxLen; k++ {
			row := make([]string, len(fields))
			copy(row, fields)
			for idx, colIdx := range cols {
				if colIdx < len(fields) {
					vList := colVals[idx]
					if k < len(vList) {
						row[colIdx] = vList[k]
					} else {
						row[colIdx] = vList[len(vList)-1]
					}
				}
			}
