	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}
	defer closer.Close()

	type groupData struct {
		keyFields []string
		rows      [][]string
	}
	var groupOrder []*groupData

	var curGroup *groupData
	var curKeyStr string

	for {
		line, err := br.ReadString('\n')
		if len(line) == 0 && err != nil {
			break
		}
