		var keyVals []string
		for _, gc := range groupCols {
			if gc < len(fields) {
				keyVals = append(keyVals, fields[gc])
			} else {
				keyVals = append(keyVals, ".")
			}
		}
		kStr := strings.Join(keyVals, "\t")

		if curGroup == nil || kStr != curKeyStr {
			curGroup = &groupData{keyFields: keyVals}
			groupOrder = append(groupOrder, curGroup)
			curKeyStr = kStr
		}
		curGroup.rows = append(curGroup.rows, fields)

		if err != nil {
			break
		}
	}

	for _, g := range groupOrder {
		out := append([]string{}, g.keyFields...)
		for i, tc := range targetCols {
			op := "collapse"
			if i < len(ops) {
				op = ops[i]
			}
			var vals []string
			for _, r := range g.rows {
				if tc < len(r) {
					vals = append(vals, r[tc])
				} else {
					vals = append(vals, ".")
				}
			}
			res := applyOp(vals, op)
			out = append(out, res)
		}
		fmt.Println(strings.Join(out, "\t"))
	}
}
