		pctAT, pctGC := 0.0, 0.0
		if tot > 0 {
			pctAT = float64(nA+nT) / float64(tot)
			pctGC = float64(nC+nG) / float64(tot)
		}

		fmt.Printf("%s\t%.7f\t%.7f\t%d\t%d\t%d\t%d\t%d\t%d\t%d\n", r.Raw, pctAT, pctGC, nA, nC, nG, nT, nN, nOth, tot)
	}
}
