package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

type FastaSeq struct {
	Header string
	Seq    []byte
}

func ReadFasta(path string) (map[string]*FastaSeq, []string, error) {
	closer, br, err := OpenStream(path)
	if err != nil {
		return nil, nil, err
	}
	defer closer.Close()

	seqMap := make(map[string]*FastaSeq)
	var order []string

	var curHeader string
	var curSeq []byte

	for {
		line, err := br.ReadString('\n')
		if len(line) == 0 && err != nil {
			break
		}
		trimmed := strings.TrimRight(line, "\r\n")
		if strings.HasPrefix(trimmed, ">") {
			if curHeader != "" {
				hdrName := strings.Fields(curHeader[1:])[0]
				seqMap[hdrName] = &FastaSeq{Header: curHeader, Seq: curSeq}
				order = append(order, hdrName)
			}
			curHeader = trimmed
			curSeq = nil
		} else {
			curSeq = append(curSeq, []byte(trimmed)...)
		}
		if err != nil {
			break
		}
	}
	if curHeader != "" {
		hdrName := strings.Fields(curHeader[1:])[0]
		seqMap[hdrName] = &FastaSeq{Header: curHeader, Seq: curSeq}
		order = append(order, hdrName)
	}

	return seqMap, order, nil
}

func reverseComplement(seq []byte) []byte {
	res := make([]byte, len(seq))
	n := len(seq)
	for i := 0; i < n; i++ {
		b := seq[n-1-i]
		switch b {
		case 'A':
			res[i] = 'T'
		case 'a':
			res[i] = 't'
		case 'C':
			res[i] = 'G'
		case 'c':
			res[i] = 'g'
		case 'G':
			res[i] = 'C'
		case 'g':
			res[i] = 'c'
		case 'T':
			res[i] = 'A'
		case 't':
			res[i] = 'a'
		case 'U':
			res[i] = 'A'
		case 'u':
			res[i] = 'a'
		default:
			res[i] = b
		}
	}
	return res
}

func runGetFasta(args []string) {
	var fastaFile string
	var bedFile string
	var outFile string
	useName := false
	useNameOnly := false
	tabMode := false
	sameStrand := false

	for i := 0; i < len(args); i++ {
