		case "-fi":
			if i+1 < len(args) {
				fastaFile = args[i+1]
				i++
			}
		case "-bed":
			if i+1 < len(args) {
				bedFile = args[i+1]
				i++
			}
		case "-fo":
			if i+1 < len(args) {
				outFile = args[i+1]
				i++
			}
		case "-name":
			useName = true
		case "-nameOnly":
			useNameOnly = true
		case "-tab":
			tabMode = true
		case "-s":
			sameStrand = true
		}
	}

	if fastaFile == "" || bedFile == "" {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/getfasta.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	faSeqs, _, errF := ReadFasta(fastaFile)
	if errF != nil {
		fmt.Fprintf(os.Stderr, "Error reading FASTA: %v\n", errF)
		os.Exit(1)
	}

	records, _, errR := ReadBedRecords(bedFile, false)
	if errR != nil {
		fmt.Fprintf(os.Stderr, "Error reading BED: %v\n", errR)
		os.Exit(1)
	}

	var outWriter io.Writer = os.Stdout
	if outFile != "" && outFile != "stdout" {
		f, err := os.Create(outFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error creating output file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		outWriter = f
	}

	for _, r := range records {
		fseq, ok := faSeqs[r.Chrom]
		if !ok {
			fmt.Fprintf(os.Stderr, "Feature (%s:%d-%d) chromosome not found in FASTA. Skipping.\n", r.Chrom, r.Start, r.End)
			continue
		}
		seqLen := int64(len(fseq.Seq))
		if r.Start < 0 || r.End > seqLen || r.Start >= r.End {
			fmt.Fprintf(os.Stderr, "Feature (%s:%d-%d) beyond the length of %s size (%d bp). Skipping.\n", r.Chrom, r.Start, r.End, r.Chrom, seqLen)
			continue
		}

		subSeq := fseq.Seq[r.Start:r.End]
		if sameStrand && r.Strand == "-" {
			subSeq = reverseComplement(subSeq)
		}

		var hdr string
		if useNameOnly && r.Name != "" {
			hdr = r.Name
		} else if useName && r.Name != "" {
			hdr = fmt.Sprintf("%s::%s:%d-%d", r.Name, r.Chrom, r.Start, r.End)
