	if errG != nil {
		fmt.Fprintf(os.Stderr, "Error reading genome: %v\n", errG)
		os.Exit(1)
	}

	r := rand.New(rand.NewSource(seed))

	// Collect chroms with length >= length
	var validChroms []string
	var chromSizes []int64
	totalBp := int64(0)

	for _, ch := range orderList {
		sz := genome[ch]
		if sz >= length {
			validChroms = append(validChroms, ch)
			chromSizes = append(chromSizes, sz-length+1)
			totalBp += sz - length + 1
		}
	}

	if len(validChroms) == 0 {
		return
	}

	for k := int64(0); k < numIntervals; k++ {
		// Pick random base across totalBp
		pickBp := r.Int64n(totalBp)
		var selChrom string
		var selStart int64

		curr := int64(0)
		for idx, ch := range validChroms {
			sz := chromSizes[idx]
			if pickBp < curr+sz {
				selChrom = ch
				selStart = pickBp - curr
				break
			}
			curr += sz
		}

