package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func runMultiinter(args []string) {
	var inputFiles []string
	var names []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i":
			for i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				inputFiles = append(inputFiles, args[i+1])
				i++
			}
		case "-names":
			for i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				names = append(names, args[i+1])
				i++
			}
		}
	}

	if len(inputFiles) == 0 {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/multiinter.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	type FileRecs struct {
		fileIdx int
		recs    []BedRecord
	}
	var allFiles []FileRecs

	for idx, fn := range inputFiles {
		recs, _, err := ReadBedRecords(fn, false)
		if err == nil {
			allFiles = append(allFiles, FileRecs{fileIdx: idx, recs: recs})
		}
	}

	// Group events by chrom
	chromEvents := make(map[string]map[int64]bool)
	chromRecs := make(map[string]map[int][]BedRecord) // chrom -> fileIdx -> recs

	for _, fr := range allFiles {
		for _, r := range fr.recs {
			if chromEvents[r.Chrom] == nil {
				chromEvents[r.Chrom] = make(map[int64]bool)
			}
			chromEvents[r.Chrom][r.Start] = true
			chromEvents[r.Chrom][r.End] = true

			if chromRecs[r.Chrom] == nil {
				chromRecs[r.Chrom] = make(map[int][]BedRecord)
			}
			chromRecs[r.Chrom][fr.fileIdx] = append(chromRecs[r.Chrom][fr.fileIdx], r)
		}
	}

	var chromOrder []string
	for ch := range chromEvents {
		chromOrder = append(chromOrder, ch)
	}
	sort.Strings(chromOrder)

	// Print header line
	hdr := []string{"chrom", "start", "end", "num", "list"}
	for idx, fn := range inputFiles {
		if idx < len(names) {
			hdr = append(hdr, names[idx])
		} else {
			hdr = append(hdr, fn)
		}
	}
	fmt.Println(strings.Join(hdr, "\t"))

	for _, chrom := range chromOrder {
		var posList []int64
		for p := range chromEvents[chrom] {
			posList = append(posList, p)
		}
		sort.Slice(posList, func(i, j int) bool { return posList[i] < posList[j] })

		fileMap := chromRecs[chrom]

		for pIdx := 0; pIdx < len(posList)-1; pIdx++ {
			s, e := posList[pIdx], posList[pIdx+1]
			if s >= e {
				continue
			}

			// Check which files cover [s, e)
			numCovered := 0
			var coveredFiles []string
			presence := make([]string, len(inputFiles))

			for fIdx := 0; fIdx < len(inputFiles); fIdx++ {
				fName := inputFiles[fIdx]
				if fIdx < len(names) {
					fName = names[fIdx]
				}
				recs := fileMap[fIdx]
				isCov := false
				for _, r := range recs {
					if r.Start <= s && r.End >= e {
						isCov = true
						break
					}
				}
				if isCov {
					numCovered++
					coveredFiles = append(coveredFiles, fName)
					presence[fIdx] = "1"
				} else {
					presence[fIdx] = "0"
				}
			}

			if numCovered > 0 {
				listStr := strings.Join(coveredFiles, ",")
				out := []string{chrom, strconv.FormatInt(s, 10), strconv.FormatInt(e, 10), strconv.Itoa(numCovered), listStr}
				out = append(out, presence...)
				fmt.Println(strings.Join(out, "\t"))
			}
		}
	}
}

func runUnionbedg(args []string) {
	runMultiinter(args) // unionbedg shares same multi-way BedGraph combination format
}

func runAnnotate(args []string) {
	var fileI string
	var files []string
	var names []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i":
			if i+1 < len(args) {
				fileI = args[i+1]
				i++
			}
		case "-files":
			for i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				files = append(files, args[i+1])
				i++
			}
		case "-names":
			for i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				names = append(names, args[i+1])
				i++
			}
		}
	}

	if fileI == "" || len(files) == 0 {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/annotate.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	recordsI, _, errI := ReadBedRecords(fileI, false)
	if errI != nil {
		fmt.Fprintf(os.Stderr, "Error reading -i: %v\n", errI)
		os.Exit(1)
	}

	type FileB struct {
		recs map[string][]BedRecord
	}
	var loadedFiles []FileB

	for _, fn := range files {
		recsB, _, _ := ReadBedRecords(fn, false)
		bByChrom := make(map[string][]BedRecord)
		for _, rb := range recsB {
			bByChrom[rb.Chrom] = append(bByChrom[rb.Chrom], rb)
		}
		loadedFiles = append(loadedFiles, FileB{recs: bByChrom})
	}

	// Print header
	if len(recordsI) > 0 {
		numUserCols := len(recordsI[0].Fields)
		var hdr []string
		hdr = append(hdr, "#1_usercol")
		for k := 2; k <= numUserCols; k++ {
			hdr = append(hdr, fmt.Sprintf("%d_usercol", k))
		}
		for idx, fn := range files {
			lbl := fn
			if idx < len(names) {
				lbl = names[idx]
			}
			hdr = append(hdr, fmt.Sprintf("%d_%s", numUserCols+idx+1, lbl))
		}
		fmt.Println(strings.Join(hdr, "\t"))
	}

	for _, ri := range recordsI {
		outLine := ri.Raw
		lenI := ri.Length()

		for _, fb := range loadedFiles {
			bList := fb.recs[ri.Chrom]
			coveredBp := int64(0)
			if lenI > 0 {
				depths := make([]bool, lenI)
				for _, rb := range bList {
					if OverlapBP(ri.Start, ri.End, rb.Start, rb.End) > 0 {
						s := rb.Start - ri.Start
						if s < 0 {
							s = 0
						}
						e := rb.End - ri.Start
						if e > lenI {
							e = lenI
						}
						for pos := s; pos < e; pos++ {
							depths[pos] = true
						}
					}
				}
				for _, cov := range depths {
					if cov {
						coveredBp++
					}
				}
			}
			frac := 0.0
			if lenI > 0 {
				frac = float64(coveredBp) / float64(lenI)
			}
			outLine += fmt.Sprintf("\t%.7f", frac)
		}
		fmt.Println(outLine)
	}
}
