			if chromEvents[r.Chrom] == nil {
				chromEvents[r.Chrom] = make(map[int64]bool)
			}
			chromEvents[r.Chrom][r.Start] = true
			chromEvents[r.Chrom][r.End] = true

			if chromRecs[r.Chrom] == nil {
				chromRecs[r.Chrom] = make(map[int][]BedRecord)
			}
			chromRecs[r.Chrom][fr.fileIdx] = append(chromRecs[r.Chrom][fr.fileIdx], r)
		}
	}

	var chromOrder []string
	for ch := range chromEvents {
		chromOrder = append(chromOrder, ch)
	}
	sort.Strings(chromOrder)

	// Print header line
	hdr := []string{"chrom", "start", "end", "num", "list"}
	for idx, fn := range inputFiles {
		if idx < len(names) {
			hdr = append(hdr, names[idx])
