		for p := range chromEvents[chrom] {
			posList = append(posList, p)
		}
		sort.Slice(posList, func(i, j int) bool { return posList[i] < posList[j] })

		fileMap := chromRecs[chrom]

		for pIdx := 0; pIdx < len(posList)-1; pIdx++ {
			s, e := posList[pIdx], posList[pIdx+1]
			if s >= e {
				continue
			}

			// Check which files cover [s, e)
			numCovered := 0
			var coveredFiles []string
			presence := make([]string, len(inputFiles))

			for fIdx := 0; fIdx < len(inputFiles); fIdx++ {
				fName := inputFiles[fIdx]
				if fIdx < len(names) {
					fName = names[fIdx]
				}
				recs := fileMap[fIdx]
