func runSplit(args []string) {
	inputFile := "stdin"
	numFiles := 1
	prefix := "split_"

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i", "--input":
			if i+1 < len(args) {
				inputFile = args[i+1]
				i++
			}
		case "-n", "--number":
			if i+1 < len(args) {
				numFiles, _ = strconv.Atoi(args[i+1])
				i++
			}
		case "-p", "--prefix":
			if i+1 < len(args) {
				prefix = args[i+1]
				i++
			}
		}
	}

	records, _, err := ReadBedRecords(inputFile, false)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	if numFiles <= 0 {
		numFiles = 1
	}

	total := len(records)
	perFile := (total + numFiles - 1) / numFiles

	for k := 0; k < numFiles; k++ {
		sIdx := k * perFile
		if sIdx >= total {
			break
		}
		eIdx := sIdx + perFile
		if eIdx > total {
			eIdx = total
		}

		outFn := fmt.Sprintf("%s%d.bed", prefix, k+1)
		f, err := os.Create(outFn)
		if err != nil {
			continue
		}
		for _, r := range records[sIdx:eIdx] {
			fmt.Fprintln(f, r.Raw)
		}
		f.Close()
	}
}

func runSummary(args []string) {
	inputFile := "stdin"
	for i := 0; i < len(args); i++ {
		if args[i] == "-i" && i+1 < len(args) {
			inputFile = args[i+1]
			i++
		}
	}

	records, _, err := ReadBedRecords(inputFile, false)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	totalFeatures := len(records)
	totalBp := int64(0)
	minLen := int64(math.MaxInt64)
	maxLen := int64(0)

	for _, r := range records {
		l := r.Length()
		totalBp += l
		if l < minLen {
			minLen = l
		}
		if l > maxLen {
			maxLen = l
		}
	}

	meanLen := 0.0
	if totalFeatures > 0 {
		meanLen = float64(totalBp) / float64(totalFeatures)
	} else {
		minLen = 0
	}

	fmt.Printf("Total features: %d\n", totalFeatures)
	fmt.Printf("Total bp: %d\n", totalBp)
	fmt.Printf("Min length: %d\n", minLen)
	fmt.Printf("Max length: %d\n", maxLen)
	fmt.Printf("Mean length: %.2f\n", meanLen)
}

func runJaccard(args []string) {
	var fileA string
	var filesB []string
	sameStrand := false
	diffStrand := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-a":
			if i+1 < len(args) {
				fileA = args[i+1]
				i++
			}
		case "-b":
			for i+1 < len(args) && args[i+1][0] != '-' {
				filesB = append(filesB, args[i+1])
				i++
			}
		case "-s":
			sameStrand = true
		case "-S":
			diffStrand = true
		}
	}

	if fileA == "" || len(filesB) == 0 {
		data, _ := helpFiles.ReadFile("src/subcmd_helps/jaccard.txt")
		fmt.Fprint(os.Stderr, string(data))
		os.Exit(1)
	}

	recordsA, _, _ := ReadBedRecords(fileA, false)
	var allRecordsB []BedRecord
	for _, fb := range filesB {
		recsB, _, _ := ReadBedRecords(fb, false)
		allRecordsB = append(allRecordsB, recsB...)
	}

	bByChrom := make(map[string][]BedRecord)
	for _, rb := range allRecordsB {
		bByChrom[rb.Chrom] = append(bByChrom[rb.Chrom], rb)
	}

	intersectionBp := int64(0)
	unionBp := int64(0)
	numIntersections := 0

	lenA := int64(0)
	for _, ra := range recordsA {
		lenA += ra.Length()
		bList := bByChrom[ra.Chrom]
		for _, rb := range bList {
			if Overlaps(&ra, &rb, 1e-9, 1e-9, false, false, sameStrand, diffStrand) {
				numIntersections++
				intersectionBp += OverlapBP(ra.Start, ra.End, rb.Start, rb.End)
			}
		}
	}

	lenB := int64(0)
	for _, rb := range allRecordsB {
		lenB += rb.Length()
	}

	unionBp = lenA + lenB - intersectionBp
	jaccard := 0.0
	if unionBp > 0 {
		jaccard = float64(intersectionBp) / float64(unionBp)
