		} else {
			dist := r.Start - lastEnd
			fmt.Printf("%s\t%d\n", r.Raw, dist)
			if r.End > lastEnd {
				lastEnd = r.End
			}
		}
	}
}

func runMakewindows(args []string) {
	var genomeFile string
	var bedFile string
	winSize := int64(0)
	stepSize := int64(0)
	winNum := int64(0)

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-g":
			if i+1 < len(args) {
				genomeFile = args[i+1]
				i++
			}
		case "-b":
			if i+1 < len(args) {
				bedFile = args[i+1]
				i++
			}
		case "-w":
			if i+1 < len(args) {
				winSize, _ = strconv.ParseInt(args[i+1], 10, 64)
				i++
			}
		case "-s":
			if i+1 < len(args) {
				stepSize, _ = strconv.ParseInt(args[i+1], 10, 64)
				i++
			}
		case "-n":
			if i+1 < len(args) {
				winNum, _ = strconv.ParseInt(args[i+1], 10, 64)
				i++
			}
		}
	}

	if stepSize == 0 && winSize > 0 {
		stepSize = winSize
	}

	if genomeFile != "" {
		genome, orderList, _ := ReadGenome(genomeFile)
		for _, chrom := range orderList {
			sz := genome[chrom]
			makeWindowsForRegion(chrom, 0, sz, winSize, stepSize, winNum, nil)
		}
		return
	}

	if bedFile != "" {
		records, _, _ := ReadBedRecords(bedFile, false)
		for _, r := range records {
			makeWindowsForRegion(r.Chrom, r.Start, r.End, winSize, stepSize, winNum, r.Fields)
		}
		return
	}

	data, _ := helpFiles.ReadFile("src/subcmd_helps/makewindows.txt")
	fmt.Fprint(os.Stderr, string(data))
	os.Exit(1)
}

func makeWindowsForRegion(chrom string, start, end, winSize, stepSize, winNum int64, extraFields []string) {
	totalLen := end - start
	if totalLen <= 0 {
		return
	}

	if winNum > 0 {
		wSize := totalLen / winNum
		rem := totalLen % winNum
		curr := start
		for i := int64(0); i < winNum; i++ {
			s := curr
			sz := wSize
			if i < rem {
				sz++
			}
			e := s + sz
			curr = e
			printWindow(chrom, s, e, extraFields)
		}
		return
	}

	if winSize > 0 {
		for s := start; s < end; s += stepSize {
			e := s + winSize
			if e > end {
				e = end
			}
			printWindow(chrom, s, e, extraFields)
		}
	}
}

func printWindow(chrom string, s, e int64, extraFields []string) {
	if len(extraFields) > 3 {
		fmt.Printf("%s\t%d\t%d\t%s\n", chrom, s, e, strings.Join(extraFields[3:], "\t"))
	} else {
		fmt.Printf("%s\t%d\t%d\n", chrom, s, e)
	}
}

func runOverlap(args []string) {
	inputFile := "stdin"
	cols1, cols2 := 2, 3

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i":
			if i+1 < len(args) {
				inputFile = args[i+1]
				i++
			}
		case "-cols":
			if i+1 < len(args) {
				parts := strings.Split(args[i+1], ",")
				if len(parts) >= 4 {
					cols1, _ = strconv.Atoi(parts[0]) // start1
					// cols2 = end1
					// cols3 = start2
					cols2, _ = strconv.Atoi(parts[3]) // end2
				}
				i++
			}
		}
	}

	closer, br, err := OpenStream(inputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}
	defer closer.Close()

	for {
		line, err := br.ReadString('\n')
		if len(line) == 0 && err != nil {
			break
		}
		trimmed := strings.TrimRight(line, "\r\n")
		if len(trimmed) == 0 || strings.HasPrefix(trimmed, "#") {
			if err != nil {
				break
			}
			continue
		}

		fields := strings.Split(trimmed, "\t")
		if len(fields) >= 6 {
			s1, _ := strconv.ParseInt(fields[cols1-1], 10, 64)
			e1, _ := strconv.ParseInt(fields[cols1], 10, 64)
			s2, _ := strconv.ParseInt(fields[cols2-1], 10, 64)
			e2, _ := strconv.ParseInt(fields[cols2], 10, 64)

			ov := OverlapBP(s1, e1, s2, e2)
			if ov <= 0 {
				// Distance gap
				if e1 <= s2 {
					ov = -(s2 - e1)
				} else if e2 <= s1 {
					ov = -(s1 - e2)
				}
			}
			fmt.Printf("%s\t%d\n", trimmed, ov)
		}

		if err != nil {
			break
		}
	}
}

