func runSplit(args []string) {
	inputFile := "stdin"
	numFiles := 1
	prefix := "split_"

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-i", "--input":
			if i+1 < len(args) {
				inputFile = args[i+1]
				i++
			}
		case "-n", "--number":
			if i+1 < len(args) {
				numFiles, _ = strconv.Atoi(args[i+1])
				i++
			}
		case "-p", "--prefix":
			if i+1 < len(args) {
				prefix = args[i+1]
				i++
			}
		}
	}

	records, _, err := ReadBedRecords(inputFile, false)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading input: %v\n", err)
		os.Exit(1)
	}

	if numFiles <= 0 {
		numFiles = 1
	}

	total := len(records)
	perFile := (total + numFiles - 1) / numFiles

	for k := 0; k < numFiles; k++ {
		sIdx := k * perFile
		if sIdx >= total {
			break
		}
		eIdx := sIdx + perFile
		if eIdx > total {
			eIdx = total
		}

		outFn := fmt.Sprintf("%s%d.bed", prefix, k+1)
		f, err := os.Create(outFn)
		if err != nil {
			continue
		}
		for _, r := range records[sIdx:eIdx] {
			fmt.Fprintln(f, r.Raw)
		}
		f.Close()
	}
}

