	}

	totalFeatures := len(records)
	totalBp := int64(0)
	minLen := int64(math.MaxInt64)
	maxLen := int64(0)

	for _, r := range records {
		l := r.Length()
		totalBp += l
		if l < minLen {
			minLen = l
		}
		if l > maxLen {
			maxLen = l
		}
	}

	meanLen := 0.0
	if totalFeatures > 0 {
		meanLen = float64(totalBp) / float64(totalFeatures)
	} else {
		minLen = 0
	}

	fmt.Printf("Total features: %d\n", totalFeatures)
